src/components/v3/VenueReadinessChecklis.before:
.venue-readiness__status {
  display: grid;
  gap: 8px;
  justify-items: end;
}

.venue-readiness__status strong {
  justify-self: end;
  padding: 5px 8px;
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 6px;
  color: #bae6fd;
  font-size: 12px;
  white-space: nowrap;
}

.venue-readiness__mobile-toggle {
  display: none;
  min-height: 38px;
  border: 1px solid rgba(56, 189, 248, 0.28);
  border-radius: 6px;
  background: rgba(14, 165, 233, 0.08);
  color: #bae6fd;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  padding: 6px 9px;
}

src/components/v3/VenueReadinessChecklis.after:
.venue-readiness__summary {
  display: list-item;
  min-block-size: 44px;
  padding-block: 8px;
  cursor: pointer;
  color: #bae6fd;
}

.venue-readiness__summary h2 {
  display: inline;
}

.venue-readiness__summary strong {
  display: block;
  margin-block-start: 6px;
  color: #bae6fd;
  font-size: 12px;
}

.venue-readiness__disclosure[open] > .venue-readiness__summary {
  margin-block-end: 14px;
}

src/components/v3/VenueReadinessChecklis.before:
.venue-readiness__status {
  justify-self: start;
  justify-items: start;
}

.venue-readiness__mobile-toggle {
  display: inline-flex;
  align-items: center;
}
